{"charges": [{"claim": "The change breaks the collapsing of multiple slashes in the pathname when there are two or more protocol-like patterns in the pathname.", "file": "index.js", "line": 165, "severity": "critical", "witnessCode": "import test from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

test('normalizeUrl collapses multiple slashes in pathname between two protocol-like patterns', t => {
  const input = 'http://example.com/foo:////bar://baz';
  const expected = 'http://example.com/foo:///bar://baz';
  const actual = normalizeUrl(input);
  assert.strictEqual(actual, expected);
});"}]}
